// Config plugin: Android 14+ Health Connect privacy-rationale entry point.
//
// The react-native-health-connect bundled plugin only adds the Android <=13
// ACTION_SHOW_PERMISSIONS_RATIONALE intent-filter. On Android 14+ the system
// instead launches a VIEW_PERMISSION_USAGE activity, so Health Connect (and
// Google Play review) require an `activity-alias` that points at MainActivity.
// Without it the "Privacy policy" link in the permission dialog is dead on 14+.
//
// Runs at prebuild (this project uses Continuous Native Generation — android/
// is gitignored and regenerated by EAS, so native config must live here).
const { withAndroidManifest } = require("@expo/config-plugins");

const ALIAS_NAME = "ViewPermissionUsageActivity";

module.exports = function withHealthConnectAndroid14(config) {
  return withAndroidManifest(config, (config) => {
    const application = config.modResults.manifest.application?.[0];
    if (!application) return config;

    application["activity-alias"] = application["activity-alias"] || [];

    const already = application["activity-alias"].some(
      (alias) => alias?.$?.["android:name"] === ALIAS_NAME,
    );
    if (already) return config;

    application["activity-alias"].push({
      $: {
        "android:name": ALIAS_NAME,
        "android:exported": "true",
        "android:targetActivity": ".MainActivity",
        "android:permission": "android.permission.START_VIEW_PERMISSION_USAGE",
      },
      "intent-filter": [
        {
          action: [
            { $: { "android:name": "android.intent.action.VIEW_PERMISSION_USAGE" } },
          ],
          category: [
            { $: { "android:name": "android.intent.category.HEALTH_PERMISSIONS" } },
          ],
        },
      ],
    });

    return config;
  });
};
